<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { estructuraProceso, guardarProceso, listarEvidencias, listarProcesos, revisarEvidencia, subirEvidencia, type EvidenciaBgc, type CriterioBgc, type PilarBgc, type ProcesoBgc } from '../services/bgc'

const procesos=ref<ProcesoBgc[]>([]),selected=ref<ProcesoBgc|null>(null),pilares=ref<PilarBgc[]>([]),evidencias=ref<EvidenciaBgc[]>([])
const loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),processModal=ref(false),evidenceModal=ref(false),criterion=ref<CriterioBgc|null>(null),file=ref<File|null>(null),description=ref(''),editingProcessId=ref<number|null>(null)
const processForm=reactive<Omit<ProcesoBgc,'id'>>({nombre:'',periodo:String(new Date().getFullYear()),descripcion:'',tipo:'carga',estado:'carga_evidencia'})
const canUpload=computed(()=>selected.value?.estado==='carga_evidencia')
const canReview=computed(()=>selected.value?.estado==='en_proceso')

async function load(){loading.value=true;error.value='';try{procesos.value=await listarProcesos();const next=selected.value?procesos.value.find(p=>p.id===selected.value?.id)||procesos.value[0]:procesos.value[0];if(next)await select(next)}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function select(process:ProcesoBgc){selected.value=process;const result=await estructuraProceso(process.id);pilares.value=result.pilares}
function openProcess(process?:ProcesoBgc){editingProcessId.value=process?.id||null;Object.assign(processForm,{nombre:process?.nombre||'',periodo:process?.periodo||String(new Date().getFullYear()),descripcion:process?.descripcion||'',tipo:process?.tipo||'carga',estado:process?.estado||'carga_evidencia'});processModal.value=true}
async function saveProcess(){if(!processForm.nombre.trim()||!processForm.periodo.trim()){error.value='Complete el nombre y periodo.';return}saving.value=true;try{await guardarProceso(editingProcessId.value,{...processForm});success.value='Proceso guardado correctamente.';processModal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function openEvidence(item:CriterioBgc){if(!selected.value)return;criterion.value=item;evidenceModal.value=true;file.value=null;description.value='';try{evidencias.value=await listarEvidencias(selected.value.id,item.id)}catch(cause){error.value=message(cause)}}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null}
async function upload(){if(!selected.value||!criterion.value||!file.value){error.value='Seleccione el archivo de evidencia.';return}saving.value=true;try{await subirEvidencia(selected.value.id,criterion.value.id,file.value,description.value);success.value='Evidencia cargada correctamente.';await openEvidence(criterion.value);await select(selected.value)}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function review(item:EvidenciaBgc,state:'aprobado'|'observado'){if(!selected.value)return;const observation=state==='observado'?prompt('Ingrese la observación:')||'':'';if(state==='observado'&&!observation)return;try{await revisarEvidencia(selected.value.id,item.id,state,observation);await openEvidence(criterion.value!);success.value=`Evidencia ${state}.`}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}
onMounted(load)
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Institucional / Buen Gobierno / Procesos</nav><header class="hero"><div class="mark">BGC</div><div><small>Buen Gobierno Corporativo</small><h1>Procesos y evidencias</h1><p>Gestiona periodos de carga, revisión y evaluación de evidencias.</p></div><button @click="openProcess()">+ Nuevo proceso</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="layout"><aside><h2>Procesos</h2><button v-for="p in procesos" :key="p.id" :class="{active:selected?.id===p.id}" @click="select(p)"><b>{{p.nombre}}</b><span>{{p.periodo}} · {{p.tipo}}</span><em>{{p.estado.replace('_',' ')}}</em></button><p v-if="!procesos.length&&!loading">No hay procesos registrados.</p></aside><main><header v-if="selected" class="process-head"><div><small>Proceso seleccionado</small><h2>{{selected.nombre}} · {{selected.periodo}}</h2><p>{{selected.descripcion}}</p></div><span :class="selected.estado">{{selected.estado.replace('_',' ')}}</span><button @click="openProcess(selected)">Editar</button></header><div v-if="loading" class="empty">Cargando información…</div><div v-else-if="!selected" class="empty">Seleccione o registre un proceso.</div><section v-for="pillar in pilares" v-else :key="pillar.id" class="pillar"><h2>{{pillar.nombre}}</h2><div v-for="standard in pillar.estandares" :key="standard.id" class="standard"><h3>{{standard.nombre}}</h3><div class="grid"><article v-for="component in standard.componentes" :key="component.id"><h4>{{component.nombre}}</h4><button v-for="item in component.criterios" :key="item.id" class="criterion" @click="openEvidence(item)"><span><small>{{item.tipo_criterio?.nombre||'Criterio'}}</small><b>{{item.nombre}}</b></span><em>{{item.evidencias_count||0}} evidencias ›</em></button></article></div></div></section></main></section>
<div v-if="processModal" class="backdrop" @mousedown.self="processModal=false"><form class="modal" @submit.prevent="saveProcess"><header><h2>Proceso BGC</h2><button type="button" @click="processModal=false">×</button></header><label>Nombre *<input v-model.trim="processForm.nombre"></label><label>Periodo *<input v-model.trim="processForm.periodo"></label><label>Tipo<select v-model="processForm.tipo"><option value="carga">Carga</option><option value="revision">Revisión</option><option value="evaluacion">Evaluación</option></select></label><label>Estado<select v-model="processForm.estado"><option value="carga_evidencia">Carga de evidencia</option><option value="en_proceso">En proceso</option><option value="cerrado">Cerrado</option></select></label><label>Descripción<textarea v-model.trim="processForm.descripcion" rows="3"/></label><footer><button type="button" class="clear" @click="processModal=false">Cancelar</button><button :disabled="saving">Guardar</button></footer></form></div>
<div v-if="evidenceModal" class="backdrop" @mousedown.self="evidenceModal=false"><section class="modal evidence"><header><div><small>Criterio</small><h2>{{criterion?.nombre}}</h2></div><button @click="evidenceModal=false">×</button></header><form v-if="canUpload" class="upload" @submit.prevent="upload"><label>Archivo *<input type="file" @change="pick"></label><label>Descripción<input v-model.trim="description"></label><button :disabled="saving">Cargar evidencia</button></form><div class="evidence-list"><p v-if="!evidencias.length">Todavía no existen evidencias.</p><article v-for="item in evidencias" :key="item.id"><div><b>{{item.archivo}}</b><span>{{item.descripcion||'Sin descripción'}} · {{item.usuario||'Usuario'}}</span></div><em :class="item.estado">{{item.estado||'pendiente'}}</em><div v-if="canReview" class="review"><button @click="review(item,'aprobado')">Aprobar</button><button class="observe" @click="review(item,'observado')">Observar</button></div><p v-if="item.observacion">{{item.observacion}}</p></article></div></section></div></div></template>

<style scoped>
.page{--accent:#7257c8;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.process-head small,.modal small,.criterion small{color:var(--accent);font-size:.56rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p,.process-head p{margin:0;color:#7d898f;font-size:.7rem}.hero>button{margin-left:auto}.hero button,.modal footer button,.upload>button,.review button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.6rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.65rem}.flash.error{color:#a13f43;background:#fff0f0}.layout{margin-top:15px;display:grid;grid-template-columns:230px 1fr;gap:14px}aside,main{border:1px solid #e1e6e9;border-radius:10px;background:#fff}aside{padding:13px}aside h2{font-size:.75rem}aside>button{width:100%;margin-bottom:7px;padding:10px;display:flex;flex-direction:column;align-items:flex-start;border:1px solid #e0e4e7;border-radius:7px;background:#fff;text-align:left}aside>button.active{border-color:var(--accent);background:#f5f2fd}aside b{font-size:.64rem}aside span,aside em{font-size:.53rem;color:#7c898f}aside em{margin-top:5px;color:var(--accent);font-style:normal;text-transform:uppercase}.process-head{padding:16px;display:flex;align-items:center;border-bottom:1px solid #e8ebed}.process-head h2{margin:2px 0;font-size:.9rem}.process-head>span{margin-left:auto;padding:5px 8px;border-radius:12px;background:#eeeafa;color:var(--accent);font-size:.53rem;text-transform:uppercase}.process-head>button{margin-left:8px;border:0;color:var(--accent);background:none}.empty{padding:60px;text-align:center;font-size:.7rem}.pillar{padding:14px}.pillar>h2{padding-bottom:8px;border-bottom:2px solid #eeeafa;font-size:.84rem}.standard>h3{font-size:.68rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.grid article{padding:10px;border:1px solid #e3e7e9;border-radius:8px}.grid h4{margin:0 0 6px;font-size:.63rem}.criterion{width:100%;padding:8px 0;display:flex;align-items:center;border:0;border-top:1px solid #edf0f2;background:none;text-align:left}.criterion span{flex:1}.criterion b{display:block;font-size:.58rem}.criterion em{font-size:.52rem;font-style:normal}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,500px);max-height:90vh;overflow:auto;padding:19px;border-radius:12px;background:#fff}.modal>header{display:flex;align-items:center}.modal h2{margin:2px 0 15px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:11px;font-size:.61rem}input,select,textarea{width:100%;margin-top:4px;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.65rem}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.upload{padding:10px;border-radius:8px;background:#f6f4fc}.evidence-list article{padding:11px 0;display:flex;align-items:center;gap:8px;flex-wrap:wrap;border-bottom:1px solid #e8ecee}.evidence-list article>div:first-child{flex:1}.evidence-list b,.evidence-list span{display:block;font-size:.59rem}.evidence-list span{color:#7d898f}.evidence-list em{padding:4px 7px;border-radius:10px;background:#fff0c9;font-size:.5rem;font-style:normal}.evidence-list em.aprobado{color:#287153;background:#e8f7ef}.evidence-list em.observado{color:#a24a3d;background:#fff0ed}.review{display:flex;gap:4px}.review .observe{background:#c16b49}.evidence-list article>p{width:100%;margin:0;color:#a24a3d;font-size:.55rem}@media(max-width:850px){.layout{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero>button{margin-left:0}}
</style>
